with enriched as (select *, max(shipping_fee) over (partition by status order by order_date, id rows between 2 preceding and current row) as last3_max_shipping_fee, avg(shipping_fee) over (partition by status order by order_date, id rows between 2 preceding and current row) as last3_avg_shipping_fee, sum(shipping_fee) over (partition by status order by order_date, id rows between 2 preceding and current row) as last3_sum_shipping_fee, sum(discount) over (partition by customer_id order by shipping_fee, id rows between unbounded preceding and current row) as cumulative_discount from orders), kept as (select s.* from enriched s where exists (select 1 from shipments c where c.order_id = s.id and c.status = 'IN_TRANSIT')), not_flagged as (select s.* from kept s where not exists (select 1 from order_items ch where ch.order_id = s.id and ch.quantity >= 3)), with_dims as (select src.id, src.customer_id, src.store_id, src.order_date, src.status, src.amount, src.shipping_fee, src.last3_sum_shipping_fee, d.region, d.opened_date, d.city from not_flagged src join stores d on src.store_id = d.id) select s.id, s.customer_id, s.store_id, s.order_date, s.status, s.shipping_fee, s.last3_sum_shipping_fee, s.region, case when region rlike '^(West|North)$' then 'OTHER_ZONE' when region rlike '^(South|East)$' then 'GROUP_B' else 'EXTENDED' end as region_zone, (select min(x.monthly_fee) from subscriptions x where x.customer_id = s.customer_id) as min_subscription_monthly_fee from with_dims s order by order_date desc nulls first, region_zone desc
